<form method="get" class="admin-filter"><input type="hidden" name="section" value="establishments"><input type="hidden" name="filter" value="<?=esc($filter)?>"><?php inputField('search','Buscar negocio',['search'=>$search??'']);?><button>Buscar</button></form>
<p><a class="pill" href="?section=establishments&amp;view=create">Registrar negocio</a> <a class="pill light" href="../reports.php?tab=billing">Gestionar suscripciones y pagos</a></p>
<div class="business-overview-table"><table><thead><tr><th>Negocio / destino</th><th>Comercial</th><th>Validación</th><th>Publicación</th><th>Siguiente acción</th><th></th></tr></thead><tbody><?php foreach($overview['rows'] as $row):?><tr><td><strong><?=esc($row['name'])?></strong><br><?=esc($row['destination'])?><br><small><?=esc($row['category'])?></small></td><td><?=esc($typeLabels[$row['participation_type']])?><?php if($row['participation_type']==='free'):?><br><small><?=esc($row['free_confirmed']?'Participación confirmada':'Participación sin confirmar')?></small><?php endif ?><?php if($row['subscription_id']):?><br><?=esc($row['plan_name']?:'Plan no indicado')?><br><span class="badge"><?=esc($termLabels[$row['subscription_state']])?></span><br><small>Fin: <?=esc($row['ends_on'])?></small><br><small><?=esc($row['has_payment']?'Pago registrado':'Sin pago registrado')?></small><?php endif ?><?php if($row['pending_payments']):?><p><a href="../reports.php?tab=billing"><?=esc($row['pending_payments'])?> pagos por comprobar</a></p><?php endif ?><?php if($row['offer_notes']):?><p><small>Propuesta: <?=esc($row['offer_notes'])?></small></p><?php endif ?></td><td><?=esc(in_array($row['information_status'],['VERIFICADO','verified'],true)?'Datos verificados':'Datos pendientes de verificar')?><br><small><?=esc(in_array($row['claim_status'],['EN_TRAMITE','under_review'],true)?'Representación en trámite':(in_array($row['claim_status'],['RECLAMADO','claimed'],true)?'Representación reclamada':'Sin reclamación registrada'))?></small><?php if($row['validation_notes']):?><p><small><?=esc($row['validation_notes'])?></small></p><?php endif ?></td><td><span class="badge"><?=esc(stateLabel($row['publication_status']))?></span><?php if($row['has_payment']&&$row['publication_status']==='draft'):?><p>Pago registrado; falta publicar</p><?php endif ?><?php if($row['publication_blockers']):?><p><small><?=esc($row['publication_blockers'])?></small></p><?php endif ?></td><td><?=esc($row['next_action']?:'Sin acción registrada')?><br><small><?=esc($row['follow_up_on']?:'Sin fecha de seguimiento')?></small></td><td><a href="?section=establishments&amp;id=<?=esc($row['id'])?>">Ver seguimiento</a></td></tr><?php endforeach ?></tbody></table></div>
